def hanoi(n, source, target, auxiliary):
    if n == 0:
        return 0
    count = hanoi(n - 1, source, auxiliary, target)
    print(f"move disk {n} from {source} to {target}")
    return count + 1 + hanoi(n - 1, auxiliary, target, source)


moves = hanoi(4, "A", "C", "B")
print(f"total moves: {moves}")
